import sys
from pathlib import Path

import torch
from torch import nn
from torchvision import models, transforms
from PIL import Image

MODEL = Path("data/models/maize_mobilenetv2.pth")

if len(sys.argv) != 2:
    raise SystemExit(
        "Usage: python scripts/ml/predict_maize.py IMAGE_PATH"
    )

image_path = Path(sys.argv[1])

if not image_path.is_file():
    raise SystemExit("Image not found")

# Trusted checkpoint generated by our own training script
checkpoint = torch.load(
    MODEL, map_location="cpu", weights_only=False
)

classes = checkpoint["classes"]

model = models.mobilenet_v2(weights=None)
model.classifier[1] = nn.Linear(
    model.last_channel, len(classes)
)
model.load_state_dict(checkpoint["model_state_dict"])
model.eval()

transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        checkpoint["normalization_mean"],
        checkpoint["normalization_std"]
    )
])

with Image.open(image_path) as img:
    image = transform(img.convert("RGB")).unsqueeze(0)

with torch.inference_mode():
    probabilities = torch.softmax(model(image), dim=1)[0]

print("\n=== TERRASCOPE MAIZE PREDICTION ===")

for index in torch.argsort(probabilities, descending=True):
    i = index.item()
    print(
        f"{classes[i]}: {probabilities[i].item():.2%}"
    )

print("\nExperimental prediction, not a confirmed diagnosis.")
